/*
 * Histórico de edições: o "Editado" do cabeçalho da postagem (PostEdited do
 * core) vira o lápis com o número de revisões do Discourse, que abre o modal
 * comparando as versões.
 *
 * Postagens editadas antes de o histórico existir (ou com o recurso
 * desligado) não têm revisões guardadas e continuam com o "Editado" do core.
 */
import app from 'flarum/forum/app';
import { override } from 'flarum/common/extend';
import PostEdited from 'flarum/forum/components/PostEdited';
import Icon from 'flarum/common/components/Icon';
import Tooltip from 'flarum/common/components/Tooltip';
import humanTime from 'flarum/common/utils/humanTime';
import extractText from 'flarum/common/utils/extractText';
import { forumBool, t } from '../../../utils/settings';
export function revisionCount(post) {
  const count = Number(post.attribute('canelaRevisionCount'));
  return Number.isFinite(count) && count > 0 ? count : 0;
}
export default function installPostHistory() {
  override(PostEdited.prototype, 'view', function (original) {
    const post = this.attrs.post;
    const count = revisionCount(post);
    if (!forumBool('canelaPostHistoryEnabled', true) || !count) return original();
    const editedUser = post.editedUser();
    const editedAt = post.editedAt();
    const info = extractText(app.translator.trans('core.forum.post.edited_tooltip', {
      user: editedUser,
      ago: editedAt ? humanTime(editedAt) : ''
    }));
    const label = `${t('extras.history.open', {
      count
    })}: ${info}`;
    return (
      // Sem `showOnFocus`: ao fechar o modal o foco volta ao botão e o
      // tooltip reapareceria sem o cursor em cima.
      m(Tooltip, {
        text: info,
        showOnFocus: false
      }, m("button", {
        type: "button",
        className: "Button--ua-reset PostEdited CanelaPostEdited",
        "aria-label": label,
        onclick: event => {
          // O modal cobre o botão e o `mouseleave` não chega: o tooltip
          // abriria (ou ficaria aberto) por cima do histórico. O `leave` do
          // tooltip também cancela o que ainda esperava o atraso para abrir.
          $(event.currentTarget).trigger('mouseleave');
          app.modal.show(() => import(/* webpackChunkName: 'forum/features/extras/history/HistoryModal', webpackMode: 'lazy-once' */ './HistoryModal'), {
            post
          });
        }
      }, m(Icon, {
        name: "fas fa-pencil"
      }), m("span", {
        className: "CanelaPostEdited-count"
      }, count)))
    );
  });
}
flarum.reg.add('ramon-canela', 'forum/features/extras/history', installPostHistory);flarum.reg.addChunkModule('forum/features/extras/history/HistoryModal', './src/forum/features/extras/history/HistoryModal.tsx', 'ramon-canela', 'forum/features/extras/history/HistoryModal');
flarum.reg.addChunkModule('forum/features/extras/history/HistoryModal', './src/forum/features/extras/history/HistoryModal.tsx', 'ramon-canela', 'forum/features/extras/history/diff');