import Extend from 'flarum/common/extenders';
import Post from 'flarum/common/models/Post';
import { SEARCH_ROUTE } from './search/route';

// A página vai num chunk próprio, carregado só quando a rota abre.
const SearchPage = () => import(/* webpackChunkName: 'forum/features/extras/search/SearchPage', webpackMode: 'lazy-once' */ './search/SearchPage');
export default [new Extend.Routes() //
.add(SEARCH_ROUTE, '/search', SearchPage), new Extend.Model(Post) //
.attribute('canelaRevisionCount')];flarum.reg.addChunkModule('forum/features/extras/search/SearchPage', './src/forum/features/extras/search/SearchPage.tsx', 'ramon-canela', 'forum/features/extras/search/SearchPage');
