flarum.reg.addChunkModule('forum/features/extras/search/SearchPage', './src/forum/features/extras/search/SearchPage.tsx', 'ramon-canela', 'forum/features/extras/search/query');
flarum.reg.addChunkModule('forum/features/extras/search/SearchPage', './src/forum/features/extras/search/SearchPage.tsx', 'ramon-canela', 'forum/features/extras/search/results');
